  str_season_maze_s1_help_disc_502 = "เมื่อผู้นำทางเข้าสู่ Unknown Dream Realms จะมีเหตุการณ์สุ่มเกิดขึ้น บางเหตุการณ์ต้องการให้วาด 3 ใบไพ่คำทำนายฝันและกำหนดผลรวมของคะแนน ความสำเร็จในการกำหนดนั้นจะได้รับรางวัลที่สอดคล้องกัน",
  str_season_maze_s1_help_disc_503 = "เมื่อเข้าสู่ Resource Dream Realms ผู้นำทางสามารถได้รับรางวัลทรัพยากรหลากหลายประเภท รวมถึง Dream Particles, Dream Insights และ Dream Orbs ยิ่งเดินทางมากขึ้นก่อนเข้าสู่ Dream Realm นี้ รางวัลที่ได้จะยิ่งมากขึ้น",
  str_season_maze_s1_help_disc_504 = "เมื่อเข้าสู่โลกความฝันที่ยังไม่เคยสำรวจ ผู้นำทางสามารถส่งออโรเรียนไปทำภารกิจเพื่อรับผลตอบแทนอย่างต่อเนื่อง ระหว่างการส่ง ออโรเรียนจะไม่สามารถร่วมสู้ได้และจะกลับมาโดยอัตโนมัติหลังจาก 5 รอบ",
  str_season_maze_s1_help_disc_505 = "เมื่อเข้าสู่ Treasure Dream Realms, ผู้นำทางสามารถเลือกรางวัลหนึ่งรายการจากหลากหลายตัวเลือกเพื่อรับไปใช้",
  str_season_maze_s1_help_disc_506 = "เมื่อเข้าสู่อุโมงค์สามารถฝัน นาวิเกเตอร์จะหน่วงการโจมตีของ Dream Devourer 1 รอบ",
  str_season_maze_s1_help_disc_507 = "การเข้าสู่ Blank Dream Realm จะไม่ทำให้เกิดผลใด ๆ",
  str_season_maze_s1_help_disc_508 = "ในโลกฝันของการทำนายทางฝัน ผู้นำทางสามารถใช้ Dream Particles เพื่อรีเซ็ตหรือลบ Dream Divination Cards ที่มีอยู่ออกไป",
  str_season_maze_s1_help_disc_509 = "ใน Trade Dream Realms, ผู้นำทางสามารถแลกเปลี่ยน Dream Orbs หลากหลายประเภทกับกันและกัน",
  str_season_maze_s1_help_disc_510 = "Safe Dream Realm เป็นที่ที่ Navigators สามารถฟื้นฟูพลัง ทำให้สามารถเรียก Aurorians, ซื้อไอเทม, ซื้อยา, หรือฟื้นคืนชีพ Aurorians เพื่อเพิ่มพลัง นอกจากนี้ การฉีด Dream Particles เข้าไปใน Dream Forge ยังสามารถปลดล็อคไอเทมที่มีพลังมากขึ้นสำหรับการท้าทายในอนาคต",
  str_season_maze_s1_help_disc_601 = "ผู้นำทางสามารถเรียกออโรเรียนเข้าร่วมในการจัดตัวละคร ออโรเรียนที่ถูกปรับใช้จะรับมรดกระดับการสร้างพัฒนาการจากภายนอกฝัน แต่จะไม่รับมรดกสถิติที่เพาะปลูกหรือระดับอื่น ๆ เพิ่มระดับการสำรวจเพื่อเพิ่มระดับของออโรเรียนและอุปกรณ์ของพวกเขาในฝัน",
  str_season_maze_s1_help_disc_602 = "Dream Gear เป็นความรู้ที่มีค่าและของสะสมที่มีค่าที่ถูกทิ้งไว้โดย Dream Wayfarers ที่กล้าหาญพอที่จะสำรวจฝันในแม่น้ำของเวลา มันสามารถกระตุ้นผลกระทบต่างๆ เพื่อช่วยเหลือนักเร่งในการสำรวจฝันของพวกเขา",
  str_season_maze_s1_help_disc_603 = "ผู้นำทางสามารถใช้พลังของ \"ไพ่ทำนายฝัน\" เพื่อเคลื่อนที่ระหว่างสังเวียนฝันที่แตกต่างกัน จำนวนขั้นตอนการกระทำบน \"ไพ่ทำนายฝัน\" จะกำหนดจำนวนสังเวียนฝันที่ผู้นำทางสามารถเคลื่อนที่ระหว่างได้ โดยบางไพ่ยังมีทรัพยากรเพิ่มเติมหรือผลกระทบพิเศษ รวมถึงแต่ไม่จำกัดเพียง Dream Particles, Particle Gain, Dream Insights, Resonance และอื่น ๆ",
  str_season_maze_s1_help_disc_604 = "ความทรงจำและความรู้สึกที่ถูกทิ้งไว้โดยผู้ฝันเดิมถูกหุ้มด้วยพลังงานฝันทีละชั้น สร้างเป็น Dream Orbs ซึ่ง Dream Orbs สามารถเพิ่มพลังการต่อสู้ของ Navigators ในฝัน ดังนั้นจงระวังอย่าให้ Dream Devourer เก็บมันไป!",
  str_season_maze_s1_help_disc_605 = "เมื่อนำเข้ามาในฝัน ไอเทมจากโลกความจริงบางครั้งจะถูกพลังงานฝันกร่อน สร้างเป็นไอเทมช่วยเหลือในฝัน แต่ละไอเทมช่วยเหลือในฝันมีผลช่วยเหลือที่ไม่ซ้ำกัน ใช้มันอย่างฉลาดเพื่อรับการสนับสนุนในการสำรวจของคุณ",
  str_season_maze_s1_guide_warn_90010101 = "คำแนะนำ: คุณได้สำเร็จในการเข้าถึงพื้นที่ฝันที่ซับซ้อนกัน ที่นี่คุณสามารถพบฝันที่คุณเคยเจอมาก่อน โปรดปฏิบัติตามคำแนะนำของผู้กระจ่างให้สว่างเพื่อสัมผัสกับกิจกรรมสำรวจที่หลากหลายและเพิ่มพลังของคุณ มุ่งหวังที่จะทำลาย Ultimate Dream Devourer และคืนความเสถียรให้กับพลังงานฝัน",
  str_season_maze_s1_guide_warn_90010102 = "เคล็ดลับ: แตะที่นี่เพื่อลงที่ในฝันและเริ่มการสำรวจของคุณ",
  str_season_maze_s1_guide_warn_90010103 = "หลังจากการสำรวจแต่ละครั้ง การแสดงผลของคุณในฝันจะถูกประเมิน และคุณจะได้รับคะแนนตามนั้น คุณสามารถรับรางวัลการสำรวจที่สอดคล้องกันเมื่อคะแนนสะสมของคุณถึงเป้าหมายที่กำหนด",
  str_season_maze_s1_guide_warn_90010104 = "เคล็ดลับเพิ่มเติม: แตะที่ข้อมูลอีเวนต์เพื่อดูรายละเอียดเพิ่มเติมเกี่ยวกับเสียงสะท้อนของฝัน",
  str_season_maze_s1_guide_warn_90010105 = "คำแนะนำ: ถ้าคุณพร้อมแล้ว แตะที่นี่เพื่อลงที่ในฝัน",
  str_season_maze_s1_guide_warn_90010201 = "คำแนะนำ: ดูเหมือนว่าคุณได้ค้นพบแล้วว่าคุณสามารถดูเควสต์ฝันที่นี่ - ทำเควสต์ฝันเพื่อได้คะแนนที่สอดคล้องกัน",
  str_season_maze_s1_guide_warn_90010202 = "ทิป: เมื่อคะแนนสะสมของคุณถึงเป้าหมายที่กำหนด คุณสามารถรับรางวัลที่สอดคล้องกันได้",
  str_season_maze_s1_guide_warn_90010203 = "คำแนะนำ: ในฝันมีเควสต์ฝันหลากหลายแบบ ในฐานะผู้กระจ่างให้สว่างของคุณ ฉันขอแนะนำให้คุณทำเควสต์ฝันเพื่อได้คะแนนเพิ่มเติม",
  str_season_maze_s1_guide_warn_90010204 = "คำแนะนำ: ที่นี่คุณสามารถดูคะแนนที่ต้องการสำหรับเหตุการณ์พิเศษถัดไปและรางวัลที่เกี่ยวข้อง จุดรางวัลจะถูกปลดล็อกอัตโนมัติหลังจากเวลาที่กำหนด หลังจากรับรางวัลทั้งหมดในปัจจุบัน คุณสามารถตรวจสอบเวลาถอยหลังเพื่อปลดล็อกจุดรางวัลถัดไป",
  str_season_maze_s1_guide_warn_90010301 = "คำแนะนำ: โดยทั่วไปแล้ว ฝันจะถูกสร้างขึ้นเป็นหลายระดับ ระดับที่สูงขึ้น ความท้าทายก็ยากขึ้น และคะแนนที่ได้จากการทำภารกิจก็มากขึ้น คุณจะสามารถท้าทายระดับถัดไปได้เมื่อทำภารกิจระดับปัจจุบันเสร็จสิ้น บางระดับจะเปิดให้ทำภารกิจอย่างทีละครั้งหลังจากผ่านไปเป็นระยะเวลาบางช่วง",
  str_season_maze_s1_guide_warn_90010302 = "กำลังวิเคราะห์สถานการณ์... ตรวจพบระดับฝันปัจจุบัน: ระดับ 1. ในฐานะผู้กระจ่างให้สว่างของคุณ ฉันแนะนำให้คุณเริ่มความท้าทายของคุณจากระดับนี้.",
  str_season_maze_s1_guide_warn_90010303 = "กำลังวิเคราะห์สถานการณ์... ตรวจพบจอมเขมือบฝันสุดท้ายกำลังทำลายในฝันนี้ ทำลายจอมเขมือบฝันสุดท้ายเพื่อคืนความสงบสุขให้กับฝันและสำเร็จการสำรวจนี้ แตะที่นี่เพื่อดูข้อมูลเพิ่มเติมเกี่ยวกับจอมเขมือบฝันสุดท้าย",
  str_season_maze_s1_guide_warn_90010304 = "เคล็ดลับ: แตะที่นี่เพื่อสลับระดับฝัน สำรวจระดับปัจจุบันให้สมบูรณ์เพื่อปลดล็อกระดับฝันถัดไปสำหรับการเข้าใช้งานในเวลาที่กำหนด",
  str_season_maze_s1_guide_warn_90010305 = "ข้อเสนอ: ตอนนี้ ด้วยฉันอยู่ข้างๆคุณ มาเริ่มการสำรวจของคุณจากด่านความฝันที่ 1 กันเถอะ",
  str_season_maze_s1_guide_circle_90010401 = "กำลังวิเคราะห์สถานการณ์... ลงจอดสำเร็จที่จุดเริ่มต้นของฝัน อย่ากลัว; ฉันจะสู้รับมันด้วยคุณในการสำรวจฝันนี้",
  str_season_maze_s1_guide_circle_90010402 = "ความเห็น: ฉันแบ่งความฝันออกเป็นสังกัดความฝันที่แตกต่างกัน โดยอิงจากการขยับขึ้นลงของพลังงานในความฝัน โปรดทราบว่าเราสามารถเดินทางระหว่างสังกัดความฝันเหล่านี้ได้ แต่ละสังกัดจะทำให้เกิดเหตุการณ์ที่แตกต่างกัน คุณต้องการทราบว่าเหตุการณ์ใดที่รอคุณอยู่ในสังกัดความฝันนี้หรือไม่?",
  str_season_maze_s1_guide_warn_90010403 = "ทิป: โดยการแตะที่ดินแดนความฝัน คุณสามารถเข้าถึงชื่อและข้อมูลโดยละเอียดของมัน หากคุณพบดินแดนความฝันที่ไม่รู้จักในภายหลัง คุณยังสามารถแตะเพื่อดูได้",
  str_season_maze_s1_guide_warn_90010404 = "ความเห็น: ฉันสามารถตรวจสอบและทำนายการไหลของพลังงานฝัน สร้างไพ่ทำนายฝันเหล่านี้ให้คุณ ขั้นตอนการดำเนินการที่อยู่ที่มุมบนซ้ายแทนจำนวนของโลกฝันที่คุณสามารถท่องเที่ยวได้ ในขณะที่ผลกระทบพิเศษที่แนบกับไพ่จะแสดงอยู่ที่มุมล่างขวา โดยปฏิบัติตามคำแนะนำบนไพ่ทำนายฝัน คุณจะหลีกเลี่ยงการติดอยู่ในที่เดียว.",
  str_season_maze_s1_guide_warn_90010405 = "ความเห็น: เลือกไพ่ทำนายฝัน แล้วแตะเล่นเพื่อดำเนินการเอฟเฟกต์ทั้งหมดบนไพ่นั้น คุณยังสามารถทำให้เกิดผลเดียวกันได้โดยการลากไพ่ทำนายฝันไปยังศูนย์กลางหน้าจอ ที่เริ่มต้นของแต่ละรอบ ฉันจะเลือกจำนวนบางส่วนของไพ่ทำนายฝันจากกองไพ่ให้คุณ",
  str_season_maze_s1_guide_warn_90010406 = "คำแนะนำ: ที่นี่คุณสามารถดูทรัพยากรทั้งหมดที่คุณได้รับระหว่างการสำรวจนี้ เช่น Dream Particles, Particle Gain, Resonance, Exploration Leve, Dream Insights ฯลฯ ถ้าคุณยังไม่คุ้นเคยกับพวกเขาก็ไม่เป็นไร ฉันเชื่อว่าเมื่อคุณสำรวจลึกซึ้งขึ้น คุณจะเข้าใจวิธีการรับและใช้พวกเขาแน่นอน",
  str_season_maze_s1_guide_warn_90010407 = "คำแนะนำ: แตะที่ข้อมูลอีเวนต์เพื่อดูรายละเอียดเพิ่มเติม",
  str_season_maze_s1_guide_warn_90010408 = "คำแนะนำ: ตอนนี้โปรดเลือกการ์ดทำนายฝันเพื่อเล่นและดูว่าจะเกิดอะไรขึ้น",
  str_season_maze_s1_guide_warn_90010501 = "ความเห็น: กรุณาสังเกตการ์ดทำนายฝันอย่างระมัดระวัง ขั้นตอนการดำเนินการที่อยู่ที่มุมบนซ้ายของการ์ดแสดงถึงจำนวนของชาติฝันที่คุณสามารถท่องเที่ยวได้ เมื่อเจอทางแยก คุณสามารถเลือกทางหนึ่งเพื่อดำเนินการต่อไป ที่ปลายของบางทางแยกมีชาติฝันการโทรพ้อร์ท ซึ่งสามารถขนส่งคุณไปยังชาติฝันอื่น ๆ",
  str_season_maze_s1_guide_warn_90010502 = "ความเห็น: นอกจากขั้นตอนการดำเนินการแล้ว ไพ่ทำนายฝันยังมอบรางวัลทรัพยากรที่หลากหลาย เช่น ฝุ่นฝัน, การได้รับฝุ่น, การสั่นไหว, ความรู้ฝัน และอื่น ๆ อีกมากมาย ตัวเลขด้านล่างแสดงถึงจำนวนรางวัลที่คุณสามารถได้รับ",
  str_season_maze_s1_guide_warn_90010503 = "ทิป: ที่นี่คุณสามารถดู Dream Insights ที่ได้รับระหว่างการสำรวจนี้ หาก Dream Insights ถึงมาตรฐานสำหรับการอัปเกรด มันจะอัปเกรดอัตโนมัติและล้าง Dream Insights ที่สะสมอยู่ การเพิ่มระดับ Dream Insight สามารถเพิ่มระดับของออโรเรียนและอุปกรณ์ และรับรางวัลทรัพยากรอื่น ๆ",
  str_season_maze_s1_guide_warn_90010504 = "คำเตือน: เพื่อรักษาความปลอดภัยของคุณในฝัน การรักษาความสัมพันธ์ที่เพียงพอกับฝันเป็นสิ่งที่จำเป็น หากความสัมพันธ์ลดลงเป็น 0 การสำรวจจะสิ้นสุดโดยอัตโนมัติ แต่ละรอบการต่อสู้จะใช้ความสัมพันธ์ 1 แต้ม ในกรณีที่ไม่สำเร็จในการต่อสู้กับ Dream Devourer คุณยังสามารถใช้ความสัมพันธ์เพื่อลองอีกครั้ง",
  str_season_maze_s1_guide_warn_90010505 = "ความเห็น: Dream Particles เป็นหน่วยที่เล็กที่สุดที่สร้างขึ้นจากพลังงานในฝัน สามารถแลกเปลี่ยนได้กับสิ่งของต่างๆ ในฝัน Particle Gain แสดงถึงจำนวน Dream Particles ที่สามารถจับได้ในเหตุการณ์ฝัน ณ ท้ายแต่ละรอบ การตัดสินจะเกิดขึ้นและให้คุณ Dream Particles เท่ากับ Particle Gain",
  str_season_maze_s1_guide_warn_90010506 = "คำแนะนำ: ใน Tool Pouch คุณสามารถตรวจสอบออโรเรียน, Dream Gear และ Dream Divination Cards ที่ถูกเพิ่มเข้าไปในไลน์อัพ หลังจากสำรวจเสร็จสิ้น Tool Pouch จะถูกล้างทิ้ง",
  str_season_maze_s1_guide_warn_90010507 = "คำเตือน: จอมเขมือบฝันได้ตรวจจับการเคลื่อนไหวของเราแล้วและจะโจมตีหลังจากผ่านไปจำนวนรอบบางรอบ ฉันเชื่อว่าคุณสามารถสั่งการทีมของคุณเพื่อทำลายมัน จอมเขมือบฝันสุดท้ายคือจอมเขมือบฝันที่มาโจมตีและเราสามารถสรุปการสำรวจนี้ได้เฉพาะเมื่อทำลายมัน",
